"""Embed the standalone generated-program readonly runtime, without package imports."""
from pathlib import Path
source = Path('lib/src/readonly_runtime.dart').read_text()
assert "'''" not in source
Path('lib/src/readonly_runtime_source.dart').write_text(
    "// Generated by tool/sync_readonly_runtime.py.\nconst readonlyRuntimeSource = r'''" + source + "''';\n")
